python3 -B - <<'PY'
import subprocess
import sys
from client import save

print('Runtime:', sys.version.split()[0])
base = {}
exec(compile(subprocess.check_output(['git', 'show', 'HEAD:payload.py'], text=True), 'HEAD:payload.py', 'exec'), base)

class RecordingTransport:
    def put(self, path, body):
        self.request = (path, body)
        return {'ok': True}

for value in ['Ada', '  Ada  ', 'Ada Lovelace', '', '   ', '\tAda\n', '\u00a0Ada\u00a0']:
    transport = RecordingTransport()
    result = save(transport, value)
    expected = {'display_name': value.strip()}
    assert transport.request == ('/settings', expected)
    assert result == {'ok': True}
    print(repr(value), 'base=', repr(base['build_payload'](value)), 'candidate=', repr(transport.request))
PY
